CREATE TABLE IF NOT EXISTS "app_users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"login" VARCHAR(255) NOT NULL UNIQUE,
	"hash_password" CHAR(60) NOT NULL,
	"email" VARCHAR(255) NOT NULL,
	"is_active" BOOLEAN NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	"removed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "persons" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"cpf_cnpj" VARCHAR(31) NOT NULL UNIQUE,
	"is_pj" BOOLEAN NOT NULL,
	"born_at" DATE,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "customers" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"person_id" INTEGER NOT NULL,
	"obs" VARCHAR(1023),
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "customer_contacts" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"customer_id" INTEGER NOT NULL,
	"type_id" SMALLINT NOT NULL,
	"data" VARCHAR(255) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "contact_types" (
	"id" SMALLINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "employees" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"person_id" INTEGER NOT NULL,
	"user_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "app_permissions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "app_user_permissions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"user_id" INTEGER NOT NULL,
	"permission_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "app_logs" (
	"id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"level" SMALLINT NOT NULL,
	"origin" TEXT NOT NULL,
	"message" TEXT NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_treatments" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"price" NUMERIC(7,2) NOT NULL,
	"duration_minutes" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	"removed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_procedures" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	"removed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_treatment_procedures" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"procedure_id" INTEGER NOT NULL,
	"treatment_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "employee_salon_treatments" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"employee_id" INTEGER NOT NULL,
	"treatment_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_pending_schedules" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"customer_data" JSONB NOT NULL,
	"schedule_data" JSONB NOT NULL,
	"rejected_at" TIMESTAMP,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_schedules" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"pending_scheduled_id" INTEGER,
	"customer_id" INTEGER NOT NULL,
	"schedule_started_at" TIMESTAMP NOT NULL,
	"schedule_ended_at" TIMESTAMP NOT NULL,
	"no_treatments" SMALLINT NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_schedule_treatments" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"employee_id" INTEGER NOT NULL,
	"schedule_id" INTEGER NOT NULL,
	"treatment_id" INTEGER NOT NULL,
	"price" NUMERIC(7,2) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_transactions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"method_id" INTEGER NOT NULL,
	"type_id" SMALLINT NOT NULL,
	"is_debit" BOOLEAN NOT NULL,
	"description" VARCHAR(1023) NOT NULL,
	"value" NUMERIC(7,2) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "transaction_types" (
	"id" SMALLINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "salon_schedule_transactions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"schedule_id" INTEGER NOT NULL,
	"transaction_id" INTEGER NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "payment_methods" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL UNIQUE,
	"description" VARCHAR(1023) NOT NULL,
	"created_at" TIMESTAMP NOT NULL,
	"updated_at" TIMESTAMP,
	"removed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

ALTER TABLE "customers"
ADD FOREIGN KEY("person_id") REFERENCES "persons"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "customer_contacts"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "customer_contacts"
ADD FOREIGN KEY("type_id") REFERENCES "contact_types"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "employees"
ADD FOREIGN KEY("person_id") REFERENCES "persons"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "employees"
ADD FOREIGN KEY("user_id") REFERENCES "app_users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app_user_permissions"
ADD FOREIGN KEY("user_id") REFERENCES "app_users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app_user_permissions"
ADD FOREIGN KEY("permission_id") REFERENCES "app_permissions"("id")
