ALTER TABLE "salon_treatment_procedures"
ADD FOREIGN KEY("treatment_id") REFERENCES "salon_treatments"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "employee_salon_treatments"
ADD FOREIGN KEY("employee_id") REFERENCES "employees"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "employee_salon_treatments"
ADD FOREIGN KEY("treatment_id") REFERENCES "salon_treatments"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedule_treatments"
ADD FOREIGN KEY("schedule_id") REFERENCES "salon_schedules"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_transactions"
ADD FOREIGN KEY("type_id") REFERENCES "transaction_types"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedule_treatments"
ADD FOREIGN KEY("treatment_id") REFERENCES "salon_treatments"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedules"
ADD FOREIGN KEY("customer_id") REFERENCES "customers"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedule_treatments"
ADD FOREIGN KEY("employee_id") REFERENCES "employees"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedule_transactions"
ADD FOREIGN KEY("schedule_id") REFERENCES "salon_schedules"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedule_transactions"
ADD FOREIGN KEY("transaction_id") REFERENCES "salon_transactions"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "salon_schedules"
ADD FOREIGN KEY("pending_scheduled_id") REFERENCES "salon_pending_schedules"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
